use crate::{dcb::*,models::*,json_store::JsonEventStore,school_projection::SchoolProjection};
pub fn run(store:&JsonEventStore<Event>,projection:&SchoolProjection){let n=std::env::var("DECIDER_STUDENTS").ok().and_then(|s|s.parse::<usize>().ok()).unwrap_or(0);if n==0{return;}let mut start=std::time::Instant::now();for i in 0..1000{let id=format!("student-{:08}",i*7919%n);assert!(!store.read(&Query{items:vec![QueryItem{tags:vec![Tag{category:"student".into(),keys:vec![id]}],types:vec![]}]}).events.is_empty());}eprintln!("PHASE tagged_point {}",start.elapsed().as_secs_f64());start=std::time::Instant::now();for i in 0..1000{let id=format!("student-{:08}",i*7919%n);let s:Student=serde_json::from_str(&serde_json::to_string(&projection.student(&id)).unwrap()).unwrap();assert_eq!(s.student_id,id);}eprintln!("PHASE projection_point_json {}",start.elapsed().as_secs_f64());}
